pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.getTokens{value: 0}();
        address user2 = address(0x5678);
        vm.deal(user2, 1 ether);
        vm.prank(user2);
        c.getTokens{value: 0}();
        uint256 balanceUser2 = c.balanceOf(user2);
        assertTrue(balanceUser2 == 999990000000000000000, "Balance does not match reference value");
    }
}
